import {
  createRunnerResponsesSession,
  createTestAdmission,
  runAgentLoop,
} from "@katalon-loki/computer-runner/agent-loop";
import { testSessionInstruction } from "@katalon-loki/computer-runner/agent-context";
import { createExecutionStatus } from "@katalon-loki/computer-runner/execution-status";
import {
  initialDesktopActionInput,
  buildBrowserRecapRequest as buildRecapRequest,
  runnerAssessmentInstruction,
} from "@katalon-loki/computer-runner/request-instructions";
import {
  createCaseEvidence,
  createRunEvidence,
} from "@katalon-loki/computer-runner/case-evidence";
import {
  estimateCost,
  validateModelSettings,
} from "@katalon-loki/computer-runner/model-settings";
import {
  defaultExecutionCallLimit,
  providerRetryPolicy,
} from "@katalon-loki/computer-runner/provider";
import {
  collectExecutionRecap,
  recapContinuation,
} from "@katalon-loki/computer-runner/browser-recap";
import { redactor, interruption } from "@katalon-loki/computer-runner/private";
import { createApplicationContextDispatcher } from "@katalon-loki/computer-runner/application-context";
import { randomBytes } from "node:crypto";
import { mkdtemp, readFile, readdir, stat } from "node:fs/promises";
import { tmpdir } from "node:os";
import { isAbsolute, join } from "node:path";
import { modelScreenshot } from "./model-screenshot.mjs";
import { AppiumDesktop } from "./appium.mjs";
import { privateDirectory, privateFile, sha256 } from "./private.mjs";

const now = () => new Date().toISOString();
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function validate(config) {
  if (process.platform !== "darwin") throw new Error("macOS host required");
  if (!config || typeof config !== "object")
    throw new TypeError("Configuration required");
  validateModelSettings(config);
  if (typeof config.scenario !== "string" || !config.scenario.trim())
    throw new TypeError("Nonempty scenario required");
  if (
    typeof config.requestAI !== "function" &&
    (typeof config.apiKey !== "string" || !config.apiKey)
  )
    throw new TypeError("Host-provided API key required");
  if (
    typeof config.app !== "string" ||
    config.app.length > 200 ||
    !config.app.includes(".") ||
    !config.app.split(".").every((part) => /^[A-Za-z0-9-]+$/.test(part))
  )
    throw new TypeError("Target app bundle ID required");
  if (config.outputDir && !isAbsolute(config.outputDir))
    throw new TypeError("Absolute outputDir required");
  if (
    config.parameters === null ||
    typeof (config.parameters ?? {}) !== "object" ||
    Array.isArray(config.parameters)
  )
    throw new TypeError("Named scalar parameters required");
  for (const [name, value] of Object.entries(config.parameters ?? {}))
    if (
      !name ||
      !["string", "number", "boolean"].includes(typeof value) ||
      (typeof value === "number" && !Number.isFinite(value))
    )
      throw new TypeError("Named scalar parameters required");
  if (config.launch !== undefined && typeof config.launch !== "boolean")
    throw new TypeError("target.launch must be boolean");
  for (const [name, maximum] of [
    ["calls", defaultExecutionCallLimit],
    ["desktopInputs", 150],
    ["ms", 2 ** 31 - 1],
  ]) {
    const value = config.limits?.[name];
    if (
      value !== undefined &&
      (!Number.isInteger(value) || value < 1 || value > maximum)
    )
      throw new TypeError(`limits.${name} must be between 1 and ${maximum}`);
  }
}

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
const desktopTools = [
  {
    type: "function",
    name: "inspect_accessibility",
    strict: true,
    description:
      "Read fresh Accessibility text for the target app. It may be incomplete.",
    parameters: {
      type: "object",
      properties: {},
      required: [],
      additionalProperties: false,
    },
  },
];

/** Run one scenario in a local macOS app. Artifacts remain private. */
export async function runScenario(config) {
  validate(config);
  const model = config.model ?? "gpt-6.1-terra";
  const out =
    config.outputDir ?? (await mkdtemp(join(tmpdir(), "loki-mac-runner-")));
  await privateDirectory(out);
  if ((await readdir(out)).length)
    throw new Error("Artifact directory must be empty");
  const { saved, save, retainEvidence } = createRunEvidence(out, privateFile);
  let sessionEvent = 0;
  const providerSession = createRunnerResponsesSession({
    apiKey: config.apiKey,
    requestAI: config.requestAI,
    record: ({ body, ...event }) => {
      const successfulResponse =
        event.phase === "response" &&
        (event.transport === "http"
          ? event.status >= 200 && event.status < 300
          : body?.type === "response.completed");
      // The numbered response or recap retains the successful body.
      return save(`provider-session-${++sessionEvent}.json`, {
        ...event,
        ...(successfulResponse ? {} : { body }),
      });
    },
  });
  const parameters = config.parameters ?? {};
  const secretNames = new Set([
    ...(config.secretParameterNames ?? []),
    ...Object.keys(parameters).filter((name) =>
      /pass(word)?|token|secret|api.?key|email/i.test(name),
    ),
  ]);
  const redact = redactor([
    config.apiKey,
    ...[...secretNames].map((name) => parameters[name]),
  ]);
  const taskId = config.taskId ?? randomBytes(8).toString("hex");
  const limits = {
    calls: config.limits?.calls ?? defaultExecutionCallLimit,
    desktopInputs: config.limits?.desktopInputs ?? Infinity,
    ms: config.limits?.ms ?? 600000,
  };
  const started = Date.now();
  const operatorSignal = config.signal;
  const executionLimit = new AbortController();
  config = {
    ...config,
    signal: operatorSignal
      ? AbortSignal.any([operatorSignal, executionLimit.signal])
      : executionLimit.signal,
  };
  const calls = [],
    actions = [],
    axReads = [],
    frames = [];
  const usage = {
    inputTokens: 0,
    outputTokens: 0,
    cachedTokens: 0,
    cacheWriteTokens: 0,
  };
  let desktop,
    captureContext,
    terminal = { actor: "harness", reason: "not-started" };
  let attempts = 0,
    estimatedCost = 0;
  let summary;
  const progress = (event) => {
    try {
      config.onProgress?.(redact.value(event));
    } catch {
      /* observation only */
    }
  };
  let stageStarted;
  let executionTimer;
  const admissionDeadline = () =>
    stageStarted === undefined ? Infinity : stageStarted + limits.ms;
  const admission = createTestAdmission({
    admissionDeadline,
    callLimit: limits.calls,
    attemptCount: () => attempts,
    reportAfterCase: Boolean(config.assessmentIds),
    check: () => check(),
    onChange: () => armExecutionBudget(),
  });
  const armExecutionBudget = () => {
    clearTimeout(executionTimer);
    if (stageStarted === undefined || admission.canFinishOrReport()) return;
    executionTimer = setTimeout(
      () =>
        executionLimit.abort(
          Object.assign(Error("Time limit"), {
            code: "loki.runner.deadline/1",
          }),
        ),
      Math.max(1, admissionDeadline() - Date.now()),
    );
  };
  const check = () => {
    if (config.signal.aborted)
      throw new Error(interruption(config.signal).reason);
    if (Date.now() >= admission.executionDeadline())
      throw new Error("Time limit");
  };
  const executionStatus = createExecutionStatus({
    initialEffort: config.reasoning ?? "low",
    effortRecovery: config.effortRecovery ?? true,
    saved,
    save,
    check,
    signal: config.signal,
    deadline: admissionDeadline,
    executionDeadlineSignal: executionLimit.signal,
    requestClarification: config.requestClarification,
    registerSensitiveAnswers: (values) => redact.addSecrets(values),
    retainEvidence,
  });
  const caseEvidence = createCaseEvidence(config.planRef, {
    platform: "desktop",
    save,
    onActiveChange: admission.onActiveChange,
    tracing: () => ({ group: async () => {}, groupEnd: async () => {} }),
  });
  const applicationContext = createApplicationContextDispatcher(
    config.applicationContext,
    {
      save,
      check,
      signal: config.signal,
      deadlineAt: () => new Date(admissionDeadline()).toISOString(),
      observe: () => ({ screen: null, path: null }),
    },
  );
  const activityCount = () =>
    actions.length + axReads.length + applicationContext.calls.length;
  const history = {};
  let explicitlyComplete = false,
    executionRecap = null,
    plannerAssessment = null;
  const reportSignal = () => config.reportSignal ?? operatorSignal;
  const capture = async (name) => {
    check();
    const { bytes, frame } = await desktop.capture();
    captureContext = frame;
    await save(name, bytes);
    await caseEvidence.screenshot(name, sha256(bytes));
    frames.push({ screenshot: name, at: now(), ...frame });
    await save("frames.json", frames);
    return {
      type: "computer_screenshot",
      image_url: `data:image/png;base64,${(await modelScreenshot(bytes)).toString("base64")}`,
      detail: "original",
    };
  };
  const execute = async (action, call, callId) => {
    check();
    if (
      !["wait", "screenshot"].includes(action.type) &&
      actions.filter(
        (row) =>
          row.status === "returned" &&
          !["wait", "screenshot"].includes(row.action.type),
      ).length >= limits.desktopInputs
    )
      throw Error("Desktop input limit");
    const row = {
      index: actions.length + 1,
      providerCall: call,
      callId,
      action: redact.value(action),
      status: "invoked",
      startedAt: now(),
    };
    actions.push(row);
    await save("actions.json", actions);
    try {
      row.geometry = captureContext;
      await desktop.execute(action);
      row.status = "returned";
    } catch (error) {
      row.status = "error";
      row.error = redact.text(String(error));
    } finally {
      row.endedAt = now();
      await save("actions.json", actions);
      await caseEvidence.action(row);
    }
    return row;
  };
  const provider = {
    deadline: admission.executionDeadline,
    send: (value, signal) => providerSession.send(value, signal),
    headersFor: (response) =>
      Object.fromEntries(
        ["x-request-id", "retry-after"].map((key) => [
          key,
          response.headers.get(key),
        ]),
      ),
    async record(number, request, { row, bodyText, body, update }) {
      const transport = {
        ...row,
        call: number,
        requestId: row.headers?.["x-request-id"] ?? null,
      };
      await save(`transport-${number}-attempt-${row.attempt}.json`, transport);
      await save(`transport-${number}.json`, transport);
      if (update) return;
      attempts++;
      executionStatus.account(request.reasoning.effort);
      if (bodyText !== undefined) {
        // A retry can replace the logical response. Keep the prior attempt
        // separately only in that case.
        if (row.retry)
          await save(
            `response-${number}-attempt-${row.attempt}.json`,
            bodyText,
          );
        await save(`response-${number}.json`, bodyText);
      }
      const bill = body?.usage ?? null,
        cost = bill ? estimateCost(bill, request.model) : null;
      if (cost !== null) estimatedCost += cost;
      if (bill) {
        usage.inputTokens += bill.input_tokens ?? 0;
        usage.outputTokens += bill.output_tokens ?? 0;
        usage.cachedTokens += bill.input_tokens_details?.cached_tokens ?? 0;
        usage.cacheWriteTokens +=
          bill.input_tokens_details?.cache_write_tokens ?? 0;
      }
      calls.push({
        call: number,
        attempt: row.attempt,
        status: row.httpStatus,
        durationMs: row.durationMs,
        usage: bill,
        estimatedCost: cost,
        requestId: transport.requestId,
        outputs: body?.output?.map((item) => item.type) ?? [],
      });
      await save("calls.json", calls);
      progress({
        call: number,
        status: row.httpStatus,
        estimatedCost: cost,
      });
    },
  };
  async function recapExecution(binding, executionElapsedMs) {
    const request = buildRecapRequest("gpt-6-luna", {
      ...binding,
      platformName: "Desktop",
      selectedTestIds: config.planRef?.selectedTestIds ?? [],
    });
    executionRecap = await collectExecutionRecap({
      request,
      apiKey: config.apiKey,
      requestAI: (value, signal) =>
        providerSession.send(value, signal, { review: true }),
      signal: reportSignal(),
      headersFor: (response) => ({
        "x-request-id": response.headers.get("x-request-id"),
      }),
      save,
      redact,
      executionElapsedMs,
      onError: (error) =>
        save("recap-error.json", { error: redact.text(String(error)) }),
      record: async ({ body }) => {
        attempts++;
        const bill = body?.usage ?? null,
          cost = bill ? estimateCost(bill, request.model) : null;
        if (cost !== null) estimatedCost += cost;
        if (bill) {
          usage.inputTokens += bill.input_tokens ?? 0;
          usage.outputTokens += bill.output_tokens ?? 0;
          usage.cachedTokens += bill.input_tokens_details?.cached_tokens ?? 0;
          usage.cacheWriteTokens +=
            bill.input_tokens_details?.cache_write_tokens ?? 0;
        }
        calls.push({
          call: attempts,
          usage: bill,
          estimatedCost: cost,
          kind: "recap",
        });
        await save("calls.json", calls);
      },
    });
  }
  try {
    check();
    await save("protocol.json", {
      taskId,
      model,
      nativeInspectionTools: desktopTools.map((tool) => tool.name),
    });
    desktop = new AppiumDesktop({
      outputDir: out,
      app: config.app,
      launch: config.launch,
      signal: config.signal,
    });
    await desktop.start();
    stageStarted = Date.now();
    armExecutionBudget();
    check();
    await save("target.json", {
      app: config.app,
      platform: "macOS",
      backend: "Appium Mac2",
      display: "main",
    });
    const initial = await capture("screen-initial.png");
    // Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
    const input = initialDesktopActionInput({
      setup:
        "The tools operate the selected local macOS app. Screenshots cover the main display. META means Command; CTRL means Control. Use computer actions and optional fresh Accessibility inspection; incomplete Accessibility does not prevent coordinate input. The existing application stays open after host cleanup.",
      sessionInstruction: testSessionInstruction.replace(
        "Web applications",
        "Applications",
      ),
      scenario: config.scenario,
      parameters,
      app: config.app,
      caseInstruction: caseEvidence.instruction,
      assessmentIds: config.assessmentIds,
      imageUrl: initial.image_url,
    });
    terminal =
      (await runAgentLoop({
        input,
        config,
        model,
        remainingCalls: admission.remainingCalls,
        attemptCount: () => attempts,
        activityCount,
        executionDeadline: admission.executionDeadline,
        check,
        save,
        saved,
        progress,
        redact,
        executionStatus,
        applicationContext,
        caseEvidence,
        provider,
        history,
        driver: {
          functions: desktopTools,
          closedTestQueue: admission.closedTestQueue,
          pendingTestLimit: admission.pendingTestLimit,
          assessmentInstruction: (ids) =>
            runnerAssessmentInstruction(ids, "desktop"),
          screenshot: (number) => capture(`screen-${number}.png`),
          async computer({ item, number, input }) {
            const errors = [];
            let screen;
            for (const action of item.actions ?? []) {
              const row = await execute(action, number, item.call_id);
              await delay(250);
              screen = await capture(`screen-${row.index}.png`);
              if (row.status === "error") {
                errors.push(row.error);
                break;
              }
            }
            screen ??= await capture(`screen-${number}.png`);
            input.push({
              type: "computer_call_output",
              call_id: item.call_id,
              output: screen,
            });
            if (errors.length)
              input.push({
                role: "user",
                content: `The last desktop input was not confirmed: ${errors.join("; ")}. Inspect the fresh screenshot before deciding another action.`,
              });
          },
          async tool({ item, number, body, input }) {
            if (item.name === "application_context_query") {
              input.push(await applicationContext.call(item, body.id, number));
              return;
            }
            if (item.name !== "inspect_accessibility")
              throw new Error("Unexposed tool requested");
            check();
            let text,
              isError = false;
            try {
              text = await desktop.inspect();
            } catch (error) {
              isError = true;
              text = redact.text(String(error));
            }
            axReads.push({ call: number, at: now(), isError, text });
            await save("ax-reads.json", axReads);
            input.push({
              type: "function_call_output",
              call_id: item.call_id,
              output: isError ? `Accessibility unavailable: ${text}` : text,
            });
          },
        },
      })) ?? terminal;
    explicitlyComplete = history.complete === true;
  } catch (error) {
    terminal = {
      actor: operatorSignal?.aborted
        ? interruption(operatorSignal).actor
        : "harness",
      reason: redact.text(String(error)),
    };
    await save("error.json", terminal);
  } finally {
    clearTimeout(executionTimer);
    const executionElapsedMs = Date.now() - started;
    const binding = recapContinuation({
      disposition: {
        state: explicitlyComplete ? "completed" : "incomplete",
        terminal,
      },
      report: executionStatus.snapshot().executionReport,
      history,
      activityCount: activityCount(),
      stoppedAtLimit:
        terminal.actor === "harness" &&
        ["API call limit", "Time limit", "Error: Desktop input limit"].includes(
          terminal.reason,
        ),
    });
    try {
      await caseEvidence.close();
      if (
        config.reviewRun &&
        config.assessmentRecap &&
        binding &&
        !reportSignal()?.aborted
      )
        await recapExecution(binding, executionElapsedMs);
      if (
        config.reviewRun &&
        desktop &&
        attempts > 0 &&
        !reportSignal()?.aborted
      ) {
        executionRecap ??= {
          schema: "loki.runner.execution-recap/1",
          steps: [],
          executionElapsedMs,
        };
        try {
          plannerAssessment = await config.reviewRun(
            {
              recap: executionRecap,
              tools: [{ type: "computer" }, ...desktopTools],
            },
            async (request) => {
              check();
              if (
                request.type === "function" &&
                request.name === "inspect_accessibility"
              )
                return await desktop.inspect();
              if (request.type === "computer")
                await execute(
                  request.action,
                  null,
                  randomBytes(8).toString("hex"),
                );
              const screen = await capture(
                `review-${randomBytes(8).toString("hex")}.png`,
              );
              return { image_url: screen.image_url };
            },
          );
          if (Array.isArray(plannerAssessment?.inspectionSteps))
            executionRecap.steps.push(
              ...plannerAssessment.inspectionSteps
                .filter((step) => typeof step === "string")
                .map((step) => redact.text(step)),
            );
        } catch (error) {
          await save("assessment-error.json", {
            error: redact.text(String(error)),
          });
        }
      }
    } catch (error) {
      await save("reporting-error.json", {
        error: redact.text(String(error)),
      }).catch(() => {});
    }
    let cleanup = { sessionDeleted: true, processClosed: true, errors: [] };
    if (desktop) {
      try {
        cleanup = await desktop.close();
      } catch (error) {
        cleanup = {
          sessionDeleted: false,
          processClosed: false,
          errors: [redact.text(String(error))],
        };
      }
    }
    try {
      await save("cleanup.json", cleanup);
      if (
        !config.reviewRun &&
        config.assessmentRecap &&
        binding &&
        !reportSignal()?.aborted
      )
        await recapExecution(binding, executionElapsedMs);
    } finally {
      providerSession?.close();
    }
    const fileNames = (await readdir(out)).filter(
      (name) => name !== "manifest.json" && name !== "result.json",
    );
    const manifest = {
      schema: "loki.mac-computer-runner.private-evidence/1",
      taskId,
      createdAt: now(),
      files: await Promise.all(
        fileNames.sort().map(async (name) => ({
          path: name,
          bytes: (await stat(join(out, name))).size,
          sha256: sha256(await readFile(join(out, name))),
        })),
      ),
    };
    await save("manifest.json", manifest);
    const returnedInputs = actions.filter(
      (row) =>
        row.status === "returned" &&
        !["wait", "screenshot"].includes(row.action.type),
    ).length;
    const result = {
      taskId,
      outputDir: out,
      model,
      reasoning: config.reasoning ?? "low",
      target: { app: config.app, platform: "macOS", backend: "Appium Mac2" },
      terminal: {
        ...redact.value(terminal),
        executionReportProvenance: executionStatus.provenance(),
      },
      ...redact.value(executionStatus.snapshot()),
      ...(executionRecap ? { executionRecap } : {}),
      ...(plannerAssessment ? { plannerAssessment } : {}),
      executionState: explicitlyComplete ? "completed" : "incomplete",
      providerRetryPolicy,
      testVerdict: "unverified",
      calls: calls.length,
      attemptedRequests: attempts,
      requestsWithoutUsage: attempts - calls.filter((row) => row.usage).length,
      returnedDesktopInputs: returnedInputs,
      axReads: axReads.length,
      elapsedMs: Date.now() - started,
      usage,
      estimatedCost,
      costPer10kInputs: returnedInputs
        ? (estimatedCost / returnedInputs) * 10000
        : null,
      costKind: "Usage-based estimate; unknown charges excluded",
      traceManifest: {
        path: join(out, "manifest.json"),
        sha256: sha256(await readFile(join(out, "manifest.json"))),
        files: manifest.files.length,
      },
      cleaned:
        cleanup.sessionDeleted &&
        cleanup.processClosed &&
        !cleanup.errors.length,
    };
    await save("result.json", result);
    progress({ result });
    summary = result;
  }
  return summary;
}

/** Integration envelope: IDs correlate, but scenario and parameters are always supplied. */
export async function run(input, options) {
  if (
    !input ||
    typeof input !== "object" ||
    !Object.hasOwn(input, "scenario") ||
    !Object.hasOwn(input, "params") ||
    !input.params ||
    typeof input.params !== "object" ||
    Array.isArray(input.params)
  )
    throw new TypeError("Full scenario and explicit params object required");
  if (!options?.apiKey && typeof options?.requestAI !== "function")
    throw new TypeError("Host-provided API key required");
  const scenario =
    typeof input.scenario === "string"
      ? input.scenario
      : JSON.stringify(input.scenario);
  const result = await runScenario({
    scenario,
    parameters: input.params,
    planRef: input.planRef,
    assessmentIds: options.runnerAssessment
      ? (input.planRef?.selectedTestIds ?? [input.scenarioId])
      : undefined,
    runnerAssessment: options.runnerAssessment,
    assessmentRecap: options.assessmentRecap,
    reviewRun: options.reviewRun,
    requestClarification: options.requestClarification,
    applicationContext: options.applicationContext,
    effortRecovery: options.effortRecovery,
    reportSignal: options.reportSignal,
    managedCore: options.managedCore,
    app: input.target?.app,
    launch: input.target?.launch,
    apiKey: options.apiKey,
    requestAI: options.requestAI,
    model: options.model,
    reasoning: options.reasoning,
    outputDir: options.artifactDirectory,
    signal: options.signal,
    onProgress: options.onEvent,
    secretParameterNames: options.secretParameterNames,
    limits: options.limits,
    taskId: input.requestId,
  });
  const correlated = {
    ...result,
    correlation: {
      requestId: input.requestId ?? null,
      scenarioId: input.scenarioId ?? null,
      planRef: input.planRef ?? null,
    },
  };
  await privateFile(join(result.outputDir, "result.json"), correlated);
  return correlated;
}
